SKIPCHECK;
FEEDSTRINGS;

['HC Driver'] = N:
  IF( ATTRN('OPX Month', !OPX Month, 'YYYYMM') <= ATTRN('OPX Version', !OPX Version, 'Last Actuals YYYYMM'), 0,
  IF( ATTRS('OPX Cost Center', !OPX Cost Center, 'Alloc Source Group') @<> '_none', 0,
      ['Headcount'] ) );

['Denom SUB']    = N: DB('OPX Alloc Driver', !OPX Version, !OPX Subsidiary,    'All Cost Centers', !OPX Month, 'HC Driver');
['Denom GLOBAL'] = N: DB('OPX Alloc Driver', !OPX Version, 'All Subsidiaries', 'All Cost Centers', !OPX Month, 'HC Driver');

FEEDERS;
['Headcount'] => ['HC Driver'];
['HC Driver'] => ['Denom SUB'], ['Denom GLOBAL'];
['HC Driver'] => DB('OPX Alloc Engine', !OPX Version, !OPX Subsidiary, !OPX Cost Center, 'Benefits', !OPX Month, 'HC Driver Eng');
['HC Driver'] => DB('OPX Alloc Engine', !OPX Version, !OPX Subsidiary, !OPX Cost Center, 'Depreciation', !OPX Month, 'HC Driver Eng');
['HC Driver'] => DB('OPX Alloc Engine', !OPX Version, !OPX Subsidiary, !OPX Cost Center, 'Facilities', !OPX Month, 'HC Driver Eng');
['HC Driver'] => DB('OPX Alloc Engine', !OPX Version, !OPX Subsidiary, !OPX Cost Center, 'IT', !OPX Month, 'HC Driver Eng');
['HC Driver'] => DB('OPX Alloc Engine', !OPX Version, !OPX Subsidiary, !OPX Cost Center, 'IS', !OPX Month, 'HC Driver Eng');

SKIPCHECK;
FEEDSTRINGS;

['Direct Expense'] = N:
  IF( ATTRS('OPX Cost Center', !OPX Cost Center, 'Alloc Source Group') @<> !OPX Allocation Group, 0,
  IF( ATTRN('OPX Month', !OPX Month, 'YYYYMM') <= ATTRN('OPX Version', !OPX Version, 'Last Actuals YYYYMM'), 0,
      DB('OPX OPEX', !OPX Version, !OPX Subsidiary, !OPX Cost Center, 'Total Non-Alloc OPEX', !OPX Month, 'Direct Input') ) );

['Pool'] = N:
  IF( ATTRS('OPX Allocation Group', !OPX Allocation Group, 'Scope') @= 'GLOBAL',
      DB('OPX Alloc Engine', !OPX Version, 'All Subsidiaries', 'All Cost Centers', !OPX Allocation Group, !OPX Month, 'Direct Expense'),
  IF( ATTRS('OPX Allocation Group', !OPX Allocation Group, 'Scope') @= 'SUB',
      DB('OPX Alloc Engine', !OPX Version, !OPX Subsidiary, 'All Cost Centers', !OPX Allocation Group, !OPX Month, 'Direct Expense'),
      0 ) );

['Denom Eff'] = N:
  IF( ATTRS('OPX Allocation Group', !OPX Allocation Group, 'Scope') @= 'GLOBAL',
      DB('OPX Alloc Driver', !OPX Version, !OPX Subsidiary, !OPX Cost Center, !OPX Month, 'Denom GLOBAL'),
  IF( ATTRS('OPX Allocation Group', !OPX Allocation Group, 'Scope') @= 'SUB',
      DB('OPX Alloc Driver', !OPX Version, !OPX Subsidiary, !OPX Cost Center, !OPX Month, 'Denom SUB'),
      0 ) );

['HC Driver Eng'] = N: DB('OPX Alloc Driver', !OPX Version, !OPX Subsidiary, !OPX Cost Center, !OPX Month, 'HC Driver');

['Share Pct'] = N: IF( ['Denom Eff'] = 0, 0, ['HC Driver Eng'] / ['Denom Eff'] );

['DR'] = N: ['Pool'] * ['Share Pct'];

['CR'] = N:
  IF( ATTRS('OPX Cost Center', !OPX Cost Center, 'Alloc Source Group') @<> !OPX Allocation Group, 0,
      -1 * ['Direct Expense'] );

['Net Posting'] = N: ['DR'] + ['CR'];

['CHK Source Received'] = N:
  IF( ATTRS('OPX Cost Center', !OPX Cost Center, 'Alloc Source Group') @= !OPX Allocation Group, ['DR'], 0 );

['CHK Pool Cleared'] = N:
  IF( ATTRS('OPX Allocation Group', !OPX Allocation Group, 'Scope') @= 'GLOBAL',
      DB('OPX Alloc Engine', !OPX Version, 'All Subsidiaries', 'All Cost Centers', !OPX Allocation Group, !OPX Month, 'DR'),
      DB('OPX Alloc Engine', !OPX Version, !OPX Subsidiary, 'All Cost Centers', !OPX Allocation Group, !OPX Month, 'DR') ) - ['Pool'];

['CHK Zero Denom'] = N: IF( ['Pool'] = 0, 0, IF( ['Denom Eff'] = 0, 1, 0 ) );

FEEDERS;
['Direct Expense'] => ['Pool'], ['CR'], ['Net Posting'], ['CHK Source Received'], ['CHK Pool Cleared'], ['CHK Zero Denom'];
['HC Driver Eng'] => ['Denom Eff'], ['Share Pct'], ['DR'], ['Pool'], ['Net Posting'], ['CHK Source Received'], ['CHK Pool Cleared'], ['CHK Zero Denom'];
['CR'] => ['Net Posting'];
['DR'] => DB('OPX OPEX', !OPX Version, !OPX Subsidiary, !OPX Cost Center, ATTRS('OPX Allocation Group', !OPX Allocation Group, 'DR Account'), !OPX Month, 'Allocation');
['CR'] => DB('OPX OPEX', !OPX Version, !OPX Subsidiary, !OPX Cost Center, ATTRS('OPX Allocation Group', !OPX Allocation Group, 'CR Account'), !OPX Month, 'Allocation');
